import json
from pathlib import Path
from PIL import Image
R=Path(__file__).parent
M=json.loads((R/'source_map.json').read_text(encoding='utf-8'))
def src(a,b=None):
 b=a if b is None else b
 ps=[p for p in M['pages'] if p['printed'] and a<=p['printed']<=b]
 return {'pdf':[p['pdf'] for p in ps],'printed':[p['printed'] for p in ps]}
def p(t):return {'type':'p','text':t}
def bullets(*a):return {'type':'bullets','items':list(a)}
def steps(title,*a):return {'type':'steps','title':title,'items':list(a)}
def table(h,rows):return {'type':'table','headers':h,'rows':rows}
def formula(t,s,e):return {'type':'formula','text':t,'symbols':s,'explanation':e}
def chapter(n):
 c=M['chapters'][n-1]
 return {'id':f'O{n:02d}','order':n,'title':f"제{n}장. {c['title']}",'source':{'pdf':c['pdf'],'printed':c['printed']},'overview':[],'flow':[],'sections':[],'codes':[],'figures':[],'key_points':[],'comparisons':[],'review':[],'checklist':[],'index_terms':[],'coverage':[],'limitations':[],'verification':{'read_pdf_pages':c['pdf'],'visually_checked_pdf_pages':[],'notes':[]}}
def sec(c,num,title,a,b,*blocks):
 s={'number':num,'title':title,'source':src(a,b),'blocks':list(blocks)};c['sections'].append(s)
 c['coverage'].append({'number':num,'title':title,'source':src(a,b),'topics':[x.get('text',x.get('title',x['type']))[:130] for x in blocks]})
def code(c,title,a,txt,meaning,process,cautions=None,excerpt=False):
 i=f"{c['id']}-E{len(c['codes'])+1:02d}"
 c['codes'].append({'id':i,'title':title,'source':src(a),'code':txt,'excerpt':excerpt,'excerpt_note':'해당 원문 그림 또는 본문 코드에서 발췌하였다.' if excerpt else '', 'meaning':meaning,'process':process,'output':'원문에 실행 결과 미제시','cautions':cautions or []})
 c['verification']['visually_checked_pdf_pages']+=src(a)['pdf']
 return {'type':'code_ref','id':i}
def fig(c,title,a,rat,caption,meaning):
 i=f"{c['id']}-F{len(c['figures'])+1:02d}";source=src(a);pdf=source['pdf'][0]
 ip=R/'images'/f'{pdf:04d}.jpg';im=Image.open(ip);w,h=im.size;box=tuple(round(v*(w if k%2==0 else h)) for k,v in enumerate(rat))
 fp=R/'assets'/f'{i}.png';fp.parent.mkdir(exist_ok=True);im.crop(box).save(fp)
 c['figures'].append({'id':i,'title':title,'file':str(fp.resolve()),'source':source,'caption':caption,'meaning':meaning,'crop':{'image':str(ip.resolve()),'bbox':box}})
 c['verification']['visually_checked_pdf_pages']+=[pdf]
 return {'type':'figure_ref','id':i}
def finish(c,keys,reviews,checks,terms):
 c['key_points']=keys;c['review']=reviews
 c['checklist']=[{'text':t,'source':src(a,b)} for t,a,b in checks]
 c['index_terms']=[{'term':t,'section':s} for t,s in terms]
 c['verification']['visually_checked_pdf_pages']=sorted(set(c['verification']['visually_checked_pdf_pages']))
 c['verification']['notes']+=['제공된 전 본문·요약·연습 문제·추가 자료·참고문헌 페이지를 검토하였다. 외부 참고문헌 내용과 새 문제 풀이를 추가하지 않았다.','원문의 구현·제품·성능 설명은 원문이 기술하는 범위와 시점을 유지하였다.']
 (R/'chapters'/f"{c['order']:02d}.json").write_text(json.dumps(c,ensure_ascii=False,indent=2),encoding='utf-8')

c=chapter(6)
c['overview']=['공유 데이터에 병행하게 접근할 때 생기는 경쟁 조건과 임계구역 문제를 정의하고, 하드웨어 명령에서 mutex 락·세마포·모니터까지 동기화 수단을 살펴본다.','상호 배제를 제공하는 것과 실행의 진행을 보장하는 것은 함께 검토해야 한다. 교착 상태·우선순위 역전 및 경합 정도에 따른 성능 차이도 이 장의 범위이다.']
c['flow']=['경쟁 조건 → 임계구역의 세 요구 조건 → Peterson의 해결안과 명령 재정렬의 한계','메모리 장벽·원자적 명령·원자적 변수 → mutex·세마포 → 모니터와 조건 변수','라이브니스 실패 → 동기화 도구의 경합별 평가']
sec(c,'6.1','배경',283,285,
 p('**협력적 프로세스**는 시스템 안의 다른 프로세스 실행에 영향을 주거나 영향을 받는다. 논리 주소 공간을 직접 공유하거나 공유 메모리·메시지 전달로 데이터를 공유할 수 있다. 병행 실행에서는 어느 명령 지점에서도 인터럽트와 실행 전환이 일어날 수 있고, 병렬 실행에서는 여러 코어의 명령 흐름이 동시에 진행된다. 공유 데이터에 대한 접근을 질서 있게 조정하지 않으면 데이터의 일관성이 손상될 수 있다.'),
 p('원문의 유한 버퍼 예는 채워진 버퍼 수를 나타내는 정수 count를 추가한다. 생산자는 항목을 넣고 count를 증가시키며 소비자는 항목을 꺼내고 감소시킨다. 각 코드는 따로 실행하면 올바르지만 count++와 count--는 각각 읽기·레지스터 계산·저장으로 나뉠 수 있다. 초기 count가 5일 때 두 연산을 병행하면 4, 5, 6이 될 수 있지만 올바른 값은 5이다.'),
 steps('원문에서 count가 4가 되는 교차 실행','생산자가 count=5를 자신의 레지스터로 읽고 6으로 증가시킨다.','소비자가 아직 5인 count를 다른 레지스터로 읽고 4로 감소시킨다.','생산자가 6을 count에 저장한 뒤 소비자가 4를 저장한다. 실제 채워진 버퍼는 5개지만 count는 4이다.'),
 p('**경쟁 상황(race condition)**은 여러 프로세스가 같은 자료를 병행하게 접근·조작하고 최종 결과가 접근의 특정 순서에 의존하는 상황이다. 원문 예에서는 한순간에 하나의 프로세스만 count를 조작하도록 보장해야 하며, 이를 위해 프로세스 동기화가 필요하다.'))
sec(c,'6.2','임계구역 문제',286,288,
 p('**임계구역(critical section)**은 적어도 하나의 다른 프로세스와 공유하는 데이터를 접근·갱신하는 코드 영역이다. 한 프로세스가 그 영역을 수행하는 동안 다른 프로세스는 자신의 해당 임계구역에서 실행할 수 없어야 한다. 임계구역 문제는 협력적으로 데이터를 공유하는 프로세스의 활동을 동기화할 프로토콜을 설계하는 문제이다.'),
 steps('프로세스의 일반 구조','진입 구역(entry section)에서 임계구역 진입 허가를 요청한다.','임계구역에서 공유 데이터를 조작한다.','퇴출 구역(exit section)을 수행하고 나머지 구역(remainder section)을 실행한다.'),
 table(['요구 조건','정확한 의미'],[['상호 배제','한 프로세스가 임계구역을 실행하면 다른 프로세스는 그들의 임계구역을 실행할 수 없다.'],['진행','임계구역이 비어 있고 진입 희망자가 있다면 나머지 구역에서 실행 중이지 않은 프로세스들만 다음 진입자 결정에 참여하며, 결정을 무한정 연기할 수 없다.'],['한정된 대기','한 프로세스의 진입 요청 이후 허가될 때까지 다른 프로세스의 임계구역 진입 횟수에 한계가 있어야 한다.']]),
 p('각 프로세스가 0이 아닌 속도로 실행된다고 가정하지만 프로세스 사이의 상대 속도는 가정하지 않는다. 커널의 열린 파일 리스트, 다음 사용 가능한 PID, 메모리 할당·프로세스 리스트·인터럽트 자료구조도 경쟁 조건에 노출된다. 단일 코어에서 공유 변수를 수정하는 동안 인터럽트를 금지할 수 있지만, 다중 처리기에 이를 적용하면 모든 처리기로 전달하는 비용과 효율 저하, 클록 갱신의 영향을 고려해야 한다.'),
 table(['커널','선점과 특성'],[['비선점형','커널 모드에서 실행 중인 프로세스는 커널을 나가거나 봉쇄되거나 자발적으로 CPU를 양보할 때까지 계속 실행한다. 원문은 한순간 커널 실행자가 하나라는 관점에서 커널 자료구조의 경쟁 조건을 설명한다.'],['선점형','커널 모드에서도 선점을 허용하므로 공유 자료구조를 신중히 보호해야 한다. SMP에서는 여러 처리기의 프로세스가 커널 모드에 있을 수 있다. 더 민첩한 응답과 실시간 프로세스의 선점에 유리하다.']]))
pet=code(c,'Peterson의 해결안: 프로세스 Pᵢ의 구조',289,'while (true) {\n    flag[i] = true;\n    turn = j;\n    while (flag[j] && turn == j)\n        ;\n\n    /* critical section */\n\n    flag[i] = false;\n\n    /*remainder section */\n}', '두 프로세스가 진입 의사와 순번을 공유하여 임계구역 진입을 조정한다.', ['flag[i]를 true로 만들고 turn을 상대 j로 지정한다.','상대가 진입 의사를 갖고 상대 차례이면 대기한다.','임계구역을 마치면 flag[i]를 false로 바꾼다.'],['공유 선언은 int turn;과 boolean flag[2];이다.','이 예는 현대 컴퓨터에서 명령 재정렬 때문에 올바른 실행을 보장할 수 없다는 원문의 제한과 함께 읽어야 한다.'],True)
sec(c,'6.3','Peterson의 해결안',288,291,
 p('Peterson의 해결안은 임계구역과 나머지 구역을 번갈아 실행하는 **두 프로세스**에 한정된다. turn은 진입 순번, flag 배열은 각 프로세스가 진입할 준비가 되었는지를 나타낸다. 두 프로세스가 함께 들어가려 하면 turn에 대한 마지막 배정이 먼저 들어갈 프로세스를 결정한다.'),pet,
 p('원문의 증명은 두 프로세스가 동시에 임계구역에 있다면 flag가 모두 true여야 하지만 turn은 동시에 두 값을 가질 수 없다는 점으로 상호 배제를 보인다. 진입을 막는 것은 상대가 진입 의사가 있고 상대 차례인 경우뿐이다. 상대가 나가면 flag를 false로 바꾸고, 다시 들어가려 해도 turn을 넘겨주므로 기다리던 프로세스가 무한정 양보하지 않는다.'),
 p('**적용 한계:** 현대 컴파일러와 프로세서는 데이터 종속성이 없는 읽기·쓰기를 재정렬할 수 있다. 원문은 x와 flag를 공유하는 두 스레드에서 x=100보다 flag=true가 먼저 보이면 기대한 100 대신 0을 출력할 수 있음을 보인다. Peterson의 진입 구역 첫 두 배정 순서가 바뀌면 두 스레드가 동시에 임계구역에 있을 수 있다. 따라서 논리적 증명만으로 현대 구조의 실행까지 보장한다고 해석하면 안 된다.'))
sec(c,'6.4','동기화를 위한 하드웨어 지원',291,297,p('원문은 메모리 장벽, 원자적 하드웨어 명령, 원자적 변수를 제시한다. 이들은 직접 동기화에 쓰이거나 더 높은 수준 도구를 만드는 기본 구성요소가 된다.'))
sec(c,'6.4.1','메모리 장벽',292,293,
 p('**메모리 모델**은 컴퓨터 구조가 프로그램의 메모리 접근에 보장하는 사항을 뜻한다. 원문은 한 처리기의 변경 결과가 다른 모든 처리기에 즉시 보이는 강한 순서와 즉시 보이지 않는 약한 순서를 구별한다. 구조마다 모델이 다르므로 공유 메모리 다중 처리기의 가시성을 임의로 가정할 수 없다.'),
 p('**메모리 장벽(memory barrier, memory fence)** 명령이 실행되면 뒤의 적재·저장 전에 앞의 적재·저장이 완료되도록 한다. 저장된 변경이 다른 처리기에 보이도록 보장하여 재정렬의 문제를 다룬다. 원문의 x/flag 예에서는 읽는 쪽에서 flag 적재 뒤 x 적재 전에, 쓰는 쪽에서는 x 배정 뒤 flag 배정 전에 장벽을 둔다. 매우 낮은 수준의 연산이며 원문은 주로 커널 개발자의 특수 동기화 코드에 사용된다고 설명한다.'))
cas=code(c,'원자적 compare_and_swap()의 정의',294,'int compare_and_swap(int *value, int expected, int new_value) {\n    int temp = *value;\n\n    if (*value == expected)\n        *value = new_value;\n\n    return temp;\n}', '현재 값이 expected와 같을 때에만 new_value를 저장하며, 성공 여부와 관계없이 원래 값을 반환한다.',['원래 *value를 temp에 보관한다.','기댓값과 현재 값이 같으면 값을 바꾼다.','temp를 반환한다. 원문은 전체 명령을 원자적 단위로 가정한다.'],['동시에 실행된 CAS 명령들은 임의의 순서로 순차 실행된다.'],True)
sec(c,'6.4.2','하드웨어 명령어',293,296,
 p('원자적 명령은 검사·변경 또는 교환을 인터럽트되지 않는 하나의 단위로 수행한다. test_and_set()은 원래 값을 반환하면서 대상을 true로 설정한다. false로 초기화한 lock을 이에 사용하면 먼저 도착한 실행자만 진입하고 나갈 때 false로 바꿀 수 있다.'),cas,
 p('CAS 상호 배제 예에서 lock은 0으로 초기화되고 compare_and_swap(&lock, 0, 1)을 반복한다. 첫 성공자는 원래 값 0을 받아 임계구역에 들어가고 퇴출 시 lock=0으로 바꾼다. 그러나 단순 반복은 상호 배제를 만족해도 **한정된 대기를 만족하지 않는다**. 원문의 별도 알고리즘은 waiting 배열을 false, lock을 0으로 초기화하고 퇴출 시 대기자를 순환 탐색한다. 다음 대기자에게 진입을 넘겨 최대 n−1번만 양보하도록 한다.'),
 p('원문의 Intel x86 설명은 cmpxchg가 CAS를 구현하고 대상 피연산자가 갱신되는 동안 lock 접두어로 버스를 잠가 원자적 실행을 강제한다고 기술한다. 여기서는 이 설명을 다른 구조의 세부 동작으로 확장하지 않는다.'))
sec(c,'6.4.3','원자적 변수',296,297,
 p('**원자적 변수**는 정수·부울 같은 기본 자료형에 원자적 연산을 제공한다. CAS는 흔히 직접 사용되기보다 이런 도구의 기초가 된다. 원문의 증가 함수는 현재 값을 읽고 그 값이 유지되어 있을 때만 1 증가시키는 CAS를 시도하며 충돌하면 반복한다.'),
 p('한 변수의 갱신이 원자적이라는 사실만으로 전체 알고리즘의 경쟁 조건이 사라지지는 않는다. 유한 버퍼에서 count가 원자적이어도 두 소비자가 count>0을 기다리다가 생산자가 항목 하나만 추가했을 때 함께 대기를 빠져나올 수 있다. 원문은 원자적 변수를 주로 카운터·시퀀스 생성기 같은 공유 데이터 한 개의 갱신에 적합한 도구로 제한하여 설명한다.'))
sec(c,'6.5','Mutex Locks',297,299,
 p('**Mutex 락**은 임계구역 진입 전에 acquire()로 획득하고 나올 때 release()로 반환하는 도구이다. available이라는 불린 값이 사용 가능 여부를 나타낸다. 획득·반환 호출은 원자적이어야 하며 CAS로 구현할 수 있다.'),
 p('원문의 단순 구현은 사용 불가능한 동안 반복 검사하는 **바쁜 대기**를 한다. 이 유형을 스핀락이라고 부른다. 하나의 CPU 코어를 여러 프로세스가 나누는 환경에서는 다른 프로세스가 쓸 CPU 주기를 낭비한다. 반면 대기하면서 문맥 교환을 하지 않는 이점이 있어 다중 코어에서 임계구역이 짧을 때 유리할 수 있다.'),
 p('원문이 제시하는 짧은 기간의 기준은 락 유지 시간이 대기와 재개를 위한 **두 번의 문맥 교환 시간보다 짧은 경우**이다. 락을 얻으려다 봉쇄되면 경합, 즉시 얻을 수 있으면 비경합으로 본다. 많은 스레드가 경쟁하는 높은 경합은 응용의 전체 성능을 떨어뜨린다.'))
wait=code(c,'대기 큐를 사용하는 세마포 wait()',301,'wait(semaphore *S) {\n    S->value--;\n    if (S->value < 0) {\n        add this process to S->list;\n        sleep();\n    }\n}', '자원 수를 감소시키고 기다려야 하는 프로세스를 세마포 대기 리스트에 넣어 일시 중지한다.',['value를 감소시킨다.','음수이면 프로세스를 list에 넣고 sleep()으로 대기시킨다.'],['원문의 의사 코드이다. 일반 C 코드로 임의 수정하지 않았다.','세마포 연산 자체는 원자적이어야 한다.'],True)
signal=code(c,'대기 큐를 사용하는 세마포 signal()',302,'signal(semaphore *S) {\n    S->value++;\n    if (S->value <= 0) {\n        remove a process P from S->list;\n        wakeup(P);\n    }\n}', '세마포 값을 증가시키고 대기자가 있으면 하나를 꺼내 준비 상태가 되도록 깨운다.',['value를 증가시킨다.','값이 0 이하이면 list의 P를 제거하고 wakeup(P)를 수행한다.'],['깨운 프로세스가 즉시 CPU에서 실행되는지는 스케줄링에 달려 있다.'],True)
sec(c,'6.6','세마포',299,303,
 p('**세마포 S**는 정수 변수이며 초기화를 제외하고 원자적인 wait()와 signal()만으로 접근한다. 원문의 고전적 wait는 S>0이 될 때까지 바쁘게 기다린 뒤 감소시키고 signal은 증가시킨다. 검사와 감소까지 인터럽트되지 않는 하나의 동작이어야 한다.'),
 table(['유형','값·용도'],[['카운팅 세마포','유한 개 자원의 접근을 제어한다. 가용 자원 수로 초기화하고 획득 때 감소, 반환 때 증가시킨다.'],['이진 세마포','0과 1의 값만 가지며 mutex 락과 유사하게 상호 배제를 제공할 수 있다.']]),
 p('세마포는 실행 순서도 조정한다. 원문은 P₁의 S₁ 뒤에 P₂의 S₂가 실행되어야 할 때 synch를 0으로 초기화하고, S₁ 뒤에 signal(synch), S₂ 앞에 wait(synch)를 둔다. 이 순서 제약은 하나의 임계구역 보호와 구별되는 용도이다.'),
 p('바쁜 대기를 줄이는 구현에서는 세마포마다 정수 value와 프로세스 리스트 list를 둔다. wait에서 기다려야 하면 프로세스를 대기 상태로 바꾸고 CPU 스케줄러가 다른 프로세스를 선택한다. signal이 깨우면 준비 완료 상태·준비 큐로 돌아간다.'),wait,signal,
 p('이 구현에서는 음수 값의 절댓값이 대기 프로세스 수를 나타낸다. 이는 고전적 정의와 달리 감소 후 검사하기 때문이다. FIFO 큐로 대기자를 관리하면 한정된 대기를 보장하는 방법이 되지만 세마포의 정확한 사용 자체가 특정 큐잉 전략에 의존하는 것은 아니다. 단일 처리기는 연산 동안 인터럽트를 막을 수 있고 SMP는 CAS·스핀락 등의 기법이 필요하다. 바쁜 대기가 완전히 사라진 것은 아니며 짧은 세마포 연산의 임계구역에 국한된다.'))
sec(c,'6.7','모니터',303,310,
 p('세마포는 호출 순서를 잘못 쓰면 발견하기 어려운 타이밍 오류를 낳는다. signal을 먼저 하고 wait를 나중에 하면 상호 배제가 깨질 수 있고, 퇴출 시 signal 대신 wait를 하면 영구 봉쇄될 수 있다. 어느 연산을 빠뜨려도 상호 배제 위반 또는 영구 대기로 이어진다. 이런 오류를 줄이기 위해 고급 언어 구조물인 모니터를 도입한다.'),
 p('**모니터**는 내부에서 상호 배제가 보장되는 연산 집합을 포함한 추상 자료형이다. 지역 변수는 내부 함수만 접근하고 다른 프로세스가 직접 표현을 사용하지 못한다. 모니터 안에서는 항상 하나의 프로세스만 활성화된다. 프로그래머가 이 제약을 직접 코딩할 필요가 줄어든다.'),
 p('**조건 변수** x의 x.wait()는 호출자를 일시 중지하고 x.signal()은 기다리는 프로세스 하나를 재개한다. 기다리는 프로세스가 없으면 조건 변수 signal은 효과가 없다. 세마포의 signal은 항상 세마포 상태에 영향을 준다는 점과 다르다.'),
 table(['신호 후 정책','실행 관계'],[['Signal and wait','신호를 보낸 P가 기다리고 재개된 Q가 모니터를 떠나거나 다른 조건을 기다린다.'],['Signal and continue','P가 계속하며 Q는 P가 모니터를 떠나거나 다른 조건을 기다릴 때까지 대기한다.'],['절충안','P가 signal 직후 모니터를 떠나 Q가 즉시 재개되도록 한다.']]),
 p('계속 실행 정책에서는 Q가 재개할 때 기다리던 논리 조건이 이미 참이 아닐 수 있다. 원문은 Java·C# 등이 모니터 개념을 편입하고 다른 언어에서도 유사한 동기화 지원을 제공한다고 설명한다.'),
 p('세마포로 signal-and-wait 모니터를 구현할 때 mutex는 1, next는 0으로 초기화한다. next-count는 신호 후 대기하는 프로세스 수를 센다. 외부 프로시저는 mutex를 획득하고 본체를 수행한 뒤 next 대기자가 있으면 그쪽에 신호하고 아니면 mutex를 반환한다. 조건 x마다 x-sem과 x-count를 0으로 두어 조건 대기자와 신호 후 양보 관계를 연결한다.'),
 p('수행 재개 순서가 FCFS만으로 충분하지 않으면 **x.wait(c)**의 정수 c를 우선순위 번호로 저장할 수 있다. x.signal()은 가장 작은 번호의 프로세스를 재개한다. 원문의 ResourceAllocator는 자원 사용을 희망하는 최대 시간이 가장 짧은 대기자에게 하나의 자원을 준다.'),
 p('고급 도구라도 잘못된 사용 순서 자체를 보장하지 않는다. 허가 없이 자원 접근·반환, 얻은 자원 미반환, 반환 전에 재요청이 가능하다. 정확성을 위해 호출 순서를 지키는지와 모니터 밖에서 공유 자원을 직접 접근하지 않는지를 확인해야 한다. 대규모·동적 시스템에서 전수 검사는 비합리적일 수 있다는 한계도 원문에 명시된다.'))
sec(c,'6.8','라이브니스',310,312,
 p('**라이브니스(liveness)**는 프로세스가 실행 수명주기 동안 진행하도록 시스템이 충족해야 할 속성이다. 무기한 대기는 진행·한정된 대기를 위반하는 라이브니스 실패이다. 바쁜 대기도 임의의 오랜 시간 지속되면 실패가 될 수 있다.'),
 p('**교착 상태**는 집합 안의 모든 프로세스가 그 집합의 다른 프로세스만 일으킬 수 있는 사건을 기다리는 상황이다. 원문은 1로 초기화한 S, Q를 두 프로세스가 서로 반대 순서로 wait하여 각자 상대의 signal을 영원히 기다리는 예를 든다.'),
 p('**우선순위 역전**은 높은 우선순위 H가 낮은 우선순위 L이 점유한 자원을 기다리는 동안 중간 우선순위 M이 L을 선점하여 H의 대기까지 길게 하는 문제이다. 원문은 세 단계 이상의 우선순위를 가진 시스템에서 설명한다. **우선순위 상속**은 해당 자원을 사용하는 L이 사용 완료까지 H의 우선순위를 물려받게 하고 이후 원래 값으로 돌려, M의 선점을 막는다. Mars Pathfinder의 반복 리셋 사례는 우선순위 상속을 활성화하여 해결한 원문 사례로 제시된다.'))
sec(c,'6.9','평가',312,314,
 p('하드웨어 명령은 낮은 수준의 기반이며 CAS로 락 없는 알고리즘도 만들 수 있다. 이런 알고리즘은 오버헤드가 낮고 확장성 장점이 있지만 개발·테스트가 어렵다. CAS는 먼저 갱신을 시도하고 충돌하면 재시도하는 낙관적 접근, 상호 배제 락은 다른 갱신자가 있다고 가정하고 먼저 획득하는 비관적 접근으로 대비된다.'),
 table(['경합','원문의 일반적 성능 지침'],[['없음','양쪽 모두 빠르지만 CAS 보호가 기존 동기화보다 다소 빠를 수 있다.'],['적당함','CAS는 대개 성공하며 실패해도 재시도가 적어 기존 동기화보다 빠를 수 있다.'],['심함','반복 충돌이 커지므로 기존 동기화가 기본적으로 CAS보다 빠르다.']]),
 p('한 개 공유 변수 갱신에는 원자적 정수가 가볍다. 임계구역 접근 보호에는 mutex가 이진 세마포보다 간단하고 오버헤드가 적어 선호되지만, 유한 개 자원 제어에는 카운팅 세마포가 적합하다. 여러 reader를 동시에 허용하는 reader-writer 락은 병행성을 높일 수 있다. 모니터·조건 변수는 사용이 간단하지만 구현에 따라 오버헤드와 높은 경합에서의 확장성 한계가 있다.'))
sec(c,'6.10','요약',315,317,p('경쟁 조건은 공유 접근의 순서 의존성에서 발생한다. 임계구역 해결은 상호 배제·진행·한정된 대기를 함께 검토해야 한다. 하드웨어의 가시성과 원자성이 소프트웨어 도구의 토대이며, 세마포·모니터도 올바른 순서와 라이브니스 점검이 필요하다. 원문 연습 문제는 인터럽트 금지와 클록, 바쁜 대기, 단일·다중 처리기에서의 스핀락, 세마포 연산의 원자성 및 공유 은행 계좌의 경쟁 조건을 점검한다. 새 답안은 만들지 않았다.'))
finish(c,['경쟁 조건의 핵심은 공유 데이터와 접근 순서에 따른 결과 변화이다.','임계구역 해법은 상호 배제·진행·한정된 대기 세 조건을 만족해야 한다.','명령 재정렬·메모리 가시성과 원자적 갱신은 구별한다.','조건 변수 signal은 대기자가 없으면 효과가 없지만 세마포 signal은 상태를 바꾼다.','상호 배제만 확인하지 말고 교착 상태·우선순위 역전·경합 성능도 점검한다.'],['공유 데이터 → 경쟁 조건 → 임계구역 프로토콜의 관계를 연결한다.','하드웨어 지원 → 원자적 변수·락 → 세마포·모니터로 추상화 수준이 높아진다.','바쁜 대기와 봉쇄 대기의 비용은 문맥 교환과 경합 정도에 따라 다르다.'],[('임계구역의 세 요구 조건과 차이를 설명할 수 있는가?',286,287),('Peterson 해결안의 두 프로세스 전제와 현대 구조에서의 한계를 설명할 수 있는가?',288,292),('세마포 대기 큐 구현에서 음수 값과 wakeup의 의미를 설명할 수 있는가?',301,303),('모니터 조건 변수의 signal과 세마포 signal의 차이를 설명할 수 있는가?',305,307),('우선순위 역전과 우선순위 상속의 관계를 설명할 수 있는가?',312,313)], [('경쟁 상황','6.1'),('임계구역','6.2'),('Peterson의 해결안','6.3'),('메모리 장벽','6.4.1'),('CAS','6.4.2'),('원자적 변수','6.4.3'),('스핀락','6.5'),('세마포','6.6'),('모니터','6.7'),('조건 변수','6.7'),('라이브니스','6.8'),('우선순위 역전','6.8')])
